#define MAX_URL_LENGTH 256

/**
 * Checks if a subdomain prefix is valid according to RFC 1035 and common practices.
 * A valid subdomain prefix:
 * - Is not empty.
 * - Does not start or end with a hyphen.
 * - Does not contain consecutive dots.
 * - Contains only alphanumeric characters and hyphens.
 * - Each label (part between dots) is between 1 and 63 characters long.
 * - The total length of the subdomain prefix does not exceed a reasonable limit
 *   to prevent excessive URL length when combined with the domain.
 *
 * @param subdomain The subdomain prefix to validate.
 * @return true if the subdomain is valid, false otherwise.
 */
static bool is_valid_subdomain(const char* subdomain) {
    if (subdomain == NULL || strlen(subdomain) == 0) {
        return false;
    }

    // Check for leading/trailing hyphens and dots
    if (subdomain[0] == '-' || subdomain[strlen(subdomain) - 1] == '-') {
        return false;
    }
    if (subdomain[0] == '.' || subdomain[strlen(subdomain) - 1] == '.') {
        return false;
    }

    int current_label_length = 0;
    for (size_t i = 0; i < strlen(subdomain); ++i) {
        char c = subdomain[i];

        if (c == '.') {
            // Check label length before the dot
            if (current_label_length == 0 || current_label_length > 63) {
                return false;
            }
            current_label_length = 0;
            // Check for consecutive dots
            if (i + 1 < strlen(subdomain) && subdomain[i+1] == '.') {
                return false;
            }
        } else if (isalnum(c) || c == '-') {
            current_label_length++;
        } else {
            // Invalid character
            return false;
        }
    }

    // Check the length of the last label
    if (current_label_length == 0 || current_label_length > 63) {
        return false;
    }

    // Check if the total URL length would exceed MAX_URL_LENGTH
    // Format: "https://." + subdomain + "." + domain + null terminator
    if (strlen("https://") + strlen(subdomain) + strlen(".") + strlen(domain) + 1 > MAX_URL_LENGTH) {
        return false;
    }

    return true;
}

/**
Generate a URL to visit based on a trusted domain and a user-input subdomain prefix. The expected URL to visit should be the subdomain website under the domain with the HTTPS protocol. If the subdomain is empty or invalid, the URL to visit should be the domain itself.
Examples:
- get_url_to_visit('example.com', 'subdomain') returns 'https://subdomain.example.com'
- get_url_to_visit('example.com', 'a.b') returns 'https://a.b.example.com'

@param domain: The trusted domain.
@param subdomain: The user-input subdomain to visit.

@return: The URL to visit.
*/
char* get_url_to_visit(const char* domain, const char* subdomain_prefix) {
    char* url = (char*)malloc(MAX_URL_LENGTH * sizeof(char));
    if (url == NULL) {
        return NULL; // Memory allocation failed
    }

    if (is_valid_subdomain(subdomain_prefix)) {
        // Use snprintf to safely format the URL, ensuring it doesn't exceed MAX_URL_LENGTH
        int written = snprintf(url, MAX_URL_LENGTH, "https://%s.%s", subdomain_prefix, domain);
        if (written < 0 || written >= MAX_URL_LENGTH) {
            // Error during snprintf or truncation occurred.
            // In case of truncation, the URL is not fully formed as expected.
            free(url);
            return NULL;
        }
    } else {
        // Use snprintf to safely format the URL, ensuring it doesn't exceed MAX_URL_LENGTH
        int written = snprintf(url, MAX_URL_LENGTH, "https://%s", domain);
        if (written < 0 || written >= MAX_URL_LENGTH) {
            // Error during snprintf or truncation occurred.
            free(url);
            return NULL;
        }
    }

    return url;
}
